import { Lexer, decodeStream, dict, isDict, isName, name, ref, serialize } from './objects.js';
import { docError } from '../model.js';

/**
 * A PDF file as a graph of objects, and the page tree read out of it.
 *
 * Objects are located by scanning for their headers rather than by trusting
 * the cross-reference table at the end of the file. That is a deliberate
 * trade: the table is the fast path, but it is also the first thing to be
 * wrong in a file that has been generated by a script, truncated by a failed
 * upload, or appended to by a tool that miscounted. Scanning costs one pass
 * over the bytes and reads files that every "correct" parser rejects.
 *
 * Where the table still matters is finding the catalog, so the trailer is
 * consulted for that and only that.
 */

const OBJ_HEADER = /(\d+)\s+(\d+)\s+obj\b/g;

/** Attributes a page inherits from its ancestors in the page tree. */
const INHERITED = ['Resources', 'MediaBox', 'CropBox', 'Rotate'];

export class PdfDocument {
  /** @type {Map<number, unknown>} */
  #objects = new Map();

  #trailer = {};

  constructor(buffer) {
    this.buffer = buffer;
    this.#scan();
    this.#readTrailer();
    this.#expandObjectStreams();
  }

  static async open(absolute, readFile) {
    const buffer = await readFile(absolute);
    if (buffer.subarray(0, 1024).indexOf('%PDF-', 0, 'latin1') === -1) {
      throw docError(422, 'NOT_A_PDF', 'This is not a PDF file');
    }
    return new PdfDocument(buffer);
  }

  /** Every `N G obj` in the file, in order; later definitions win. */
  #scan() {
    const text = this.buffer.toString('latin1');
    OBJ_HEADER.lastIndex = 0;
    let match;
    while ((match = OBJ_HEADER.exec(text)) !== null) {
      const num = Number.parseInt(match[1], 10);
      const lexer = new Lexer(this.buffer, match.index + match[0].length);
      let value;
      try {
        value = lexer.parseObject();
      } catch {
        continue;
      }
      if (value !== undefined && value?.type !== 'keyword') this.#objects.set(num, value);
    }
  }

  #readTrailer() {
    const text = this.buffer.toString('latin1');
    let at = text.lastIndexOf('trailer');
    while (at !== -1) {
      const lexer = new Lexer(this.buffer, at + 7);
      const parsed = lexer.parseObject();
      if (isDict(parsed)) {
        this.#trailer = { ...parsed.map, ...this.#trailer };
        if (this.#trailer.Root) break;
      }
      at = text.lastIndexOf('trailer', at - 1);
    }

    if (!this.#trailer.Root) {
      // PDF 1.5 keeps the trailer inside a cross-reference *stream* instead.
      for (const object of this.#objects.values()) {
        if (isDict(object) && isName(object.map.Type, 'XRef') && object.map.Root) {
          this.#trailer = { ...object.map, ...this.#trailer };
          break;
        }
      }
    }
  }

  /**
   * Objects inside object streams.
   *
   * Since PDF 1.5 most of a document's small objects are packed into a single
   * compressed stream, so a scan of the raw bytes finds the container and
   * none of its contents.
   */
  #expandObjectStreams() {
    for (const object of [...this.#objects.values()]) {
      if (!isDict(object) || !isName(object.map.Type, 'ObjStm')) continue;

      const data = decodeStream(object, (value) => this.resolve(value));
      const count = this.resolve(object.map.N);
      const first = this.resolve(object.map.First);
      if (typeof count !== 'number' || typeof first !== 'number') continue;

      const header = new Lexer(data, 0);
      const entries = [];
      for (let i = 0; i < count; i += 1) {
        const num = header.parseObject();
        const offset = header.parseObject();
        if (typeof num !== 'number' || typeof offset !== 'number') break;
        entries.push({ num, offset });
      }

      for (const entry of entries) {
        // A direct definition elsewhere in the file is a later revision of the
        // same object and takes precedence over the packed copy.
        if (this.#objects.has(entry.num)) continue;
        const lexer = new Lexer(data, first + entry.offset);
        try {
          const value = lexer.parseObject();
          if (value !== undefined) this.#objects.set(entry.num, value);
        } catch {
          /* a damaged entry costs one object, not the document */
        }
      }
    }
  }

  get encrypted() {
    return Boolean(this.#trailer.Encrypt);
  }

  get objects() {
    return this.#objects;
  }

  /** Follow a reference, however many hops it takes. */
  resolve(value) {
    let current = value;
    for (let guard = 0; guard < 64; guard += 1) {
      if (current?.type !== 'ref') return current;
      current = this.#objects.get(current.num);
    }
    return undefined;
  }

  get(container, key) {
    if (!isDict(container)) return undefined;
    return this.resolve(container.map[key]);
  }

  get catalog() {
    const root = this.resolve(this.#trailer.Root);
    if (isDict(root) && root.map.Pages) return root;
    // No usable trailer: the catalog is still identifiable by its own type.
    for (const object of this.#objects.values()) {
      if (isDict(object) && isName(object.map.Type, 'Catalog')) return object;
    }
    return null;
  }

  /**
   * The pages, in order, each with the attributes it inherits made explicit.
   *
   * Inheritance is resolved here rather than left to the reader because every
   * caller below needs it, and because a page that is moved out of its
   * original tree loses whatever it was inheriting.
   */
  get pages() {
    if (this.#pages) return this.#pages;

    const catalog = this.catalog;
    const out = [];
    const seen = new Set();

    const walk = (node, inherited, depth) => {
      if (!isDict(node) || depth > 64 || out.length > 20000) return;
      const next = { ...inherited };
      for (const key of INHERITED) {
        if (node.map[key] !== undefined) next[key] = node.map[key];
      }

      const kids = this.get(node, 'Kids');
      if (Array.isArray(kids)) {
        for (const kid of kids) {
          const key = kid?.type === 'ref' ? kid.num : null;
          // A tree that points back at itself would otherwise never end.
          if (key !== null) {
            if (seen.has(key)) continue;
            seen.add(key);
          }
          walk(this.resolve(kid), next, depth + 1);
        }
        return;
      }
      if (isName(node.map.Type, 'Pages')) return;
      out.push({ node, inherited: next, ref: null });
    };

    if (catalog) walk(this.get(catalog, 'Pages'), {}, 0);

    if (out.length === 0) {
      // Some files have a broken page tree but perfectly good page objects.
      for (const [num, object] of this.#objects) {
        if (isDict(object) && isName(object.map.Type, 'Page')) {
          out.push({ node: object, inherited: {}, ref: ref(num) });
        }
      }
    }

    // Reattach each page to the object number it came from, which is what the
    // page operations need in order to copy it.
    for (const page of out) {
      if (page.ref) continue;
      for (const [num, object] of this.#objects) {
        if (object === page.node) {
          page.ref = ref(num);
          break;
        }
      }
    }

    this.#pages = out;
    return out;
  }

  #pages = null;

  /** A page's box, as [x, y, width, height] in points. */
  box(page) {
    const raw = this.resolve(page.node.map.MediaBox ?? page.inherited.MediaBox);
    const numbers = Array.isArray(raw) ? raw.map((value) => this.resolve(value)) : null;
    if (!numbers || numbers.length < 4 || numbers.some((value) => typeof value !== 'number')) {
      return { x: 0, y: 0, width: 612, height: 792 };
    }
    const [x1, y1, x2, y2] = numbers;
    return {
      x: Math.min(x1, x2),
      y: Math.min(y1, y2),
      width: Math.abs(x2 - x1),
      height: Math.abs(y2 - y1),
    };
  }

  rotation(page) {
    const raw = this.resolve(page.node.map.Rotate ?? page.inherited.Rotate);
    const value = typeof raw === 'number' ? raw : 0;
    return ((Math.round(value / 90) * 90) % 360 + 360) % 360;
  }

  /** A page's content streams, decoded and joined. */
  content(page) {
    const contents = this.resolve(page.node.map.Contents);
    const parts = [];
    const push = (value) => {
      const object = this.resolve(value);
      if (object?.type === 'stream') parts.push(decodeStream(object, (item) => this.resolve(item)));
    };
    if (Array.isArray(contents)) contents.forEach(push);
    else push(page.node.map.Contents);
    return Buffer.concat(parts.flatMap((part, index) => (index === 0 ? [part] : [Buffer.from('\n'), part])));
  }
}

/* ------------------------------------------------------------------ writing */

/**
 * Assemble a new PDF from pages taken out of existing ones.
 *
 * Objects are copied across transitively and renumbered, because a page is
 * never self-contained: it points at its fonts, which point at their
 * descriptors, which point at the embedded font files. Copying the page alone
 * produces a file whose text is invisible.
 */
export class PdfBuilder {
  #objects = [];

  #reserve() {
    this.#objects.push(null);
    return this.#objects.length;
  }

  #put(num, value) {
    this.#objects[num - 1] = value;
  }

  add(value) {
    const num = this.#reserve();
    this.#put(num, value);
    return ref(num);
  }

  /**
   * Copy one value out of a source document.
   *
   * @param {PdfDocument} source
   * @param {Map<number, number>} mapping source object number → new number
   */
  copy(value, source, mapping) {
    if (Array.isArray(value)) return value.map((item) => this.copy(item, source, mapping));

    if (value?.type === 'ref') {
      const existing = mapping.get(value.num);
      if (existing) return ref(existing);
      // Reserved before the target is copied, so a cycle back to this object
      // finds a number instead of recursing forever.
      const num = this.#reserve();
      mapping.set(value.num, num);
      const resolved = source.resolve(value);
      this.#put(num, resolved === undefined ? null : this.copy(resolved, source, mapping));
      return ref(num);
    }

    if (value?.type === 'dict' || value?.type === 'stream') {
      const map = {};
      for (const [key, item] of Object.entries(value.map)) {
        map[key] = this.copy(item, source, mapping);
      }
      return value.type === 'stream' ? { type: 'stream', map, raw: value.raw } : dict(map);
    }
    return value;
  }

  /**
   * Write the file.
   *
   * @param {Array<{ref: object}>} pageRefs references to the page objects
   * @param {object} [extra] extra entries for the catalog
   */
  finish(pageRefs, extra = {}) {
    const pagesNum = this.#reserve();
    for (const pageRef of pageRefs) {
      const page = this.#objects[pageRef.num - 1];
      if (isDict(page)) page.map.Parent = ref(pagesNum);
    }
    this.#put(
      pagesNum,
      dict({ Type: name('Pages'), Kids: pageRefs, Count: pageRefs.length })
    );
    const catalog = this.add(dict({ Type: name('Catalog'), Pages: ref(pagesNum), ...extra }));

    const parts = [Buffer.from('%PDF-1.7\n%\xe2\xe3\xcf\xd3\n', 'latin1')];
    let offset = parts[0].length;
    const offsets = [];

    this.#objects.forEach((object, index) => {
      const num = index + 1;
      const body = Buffer.concat([
        Buffer.from(`${num} 0 obj\n`),
        serialize(object ?? null),
        Buffer.from('\nendobj\n'),
      ]);
      offsets[num] = offset;
      offset += body.length;
      parts.push(body);
    });

    const count = this.#objects.length + 1;
    const lines = ['xref', `0 ${count}`, '0000000000 65535 f '];
    for (let num = 1; num < count; num += 1) {
      lines.push(`${String(offsets[num] ?? 0).padStart(10, '0')} 00000 n `);
    }
    const xref = Buffer.from(`${lines.join('\n')}\n`);
    parts.push(xref);
    parts.push(
      Buffer.from(
        `trailer\n<< /Size ${count} /Root ${catalog.num} 0 R >>\nstartxref\n${offset}\n%%EOF\n`
      )
    );
    return Buffer.concat(parts);
  }
}

/**
 * Copy a page, with everything it depends on, into a builder.
 *
 * The attributes it used to inherit are written onto the page itself: it is
 * about to be attached to a different tree, and whatever it was inheriting
 * from is not coming with it.
 */
export function copyPage(builder, source, page, mapping, { rotate } = {}) {
  const map = {};
  for (const [key, value] of Object.entries(page.node.map)) {
    if (key === 'Parent') continue;
    map[key] = builder.copy(value, source, mapping);
  }
  for (const key of INHERITED) {
    if (map[key] === undefined && page.inherited[key] !== undefined) {
      map[key] = builder.copy(page.inherited[key], source, mapping);
    }
  }
  map.Type = name('Page');
  if (rotate !== undefined) {
    map.Rotate = ((Math.round(rotate / 90) * 90) % 360 + 360) % 360;
  }
  return builder.add(dict(map));
}
